import React, { createContext, useState, useContext, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { login as loginService, register as registerService, logout as logoutService, getCurrentUser } from '../services/auth';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();

    useEffect(() => {
        let isMounted = true;

        const initializeAuth = async () => {
            const token = localStorage.getItem('token');
            console.log('Initial token check:', token);

            if (token) {
                try {
                    const userData = await getCurrentUser();
                    console.log('User data from getCurrentUser:', userData);
                    if (isMounted) {
                        setUser(userData);
                    }
                } catch (error) {
                    console.error('Error getting current user:', error);
                    if (isMounted) {
                        localStorage.removeItem('token');
                        navigate('/login');
                    }
                }
            } else {
                console.log('No token found, redirecting to login');
                if (isMounted) {
                    navigate('/login');
                }
            }

            if (isMounted) {
                setLoading(false);
            }
        };

        initializeAuth();

        return () => {
            isMounted = false;
        };
    }, [navigate]); // Only run on mount and when navigate changes

    const login = async (email, password) => {
        try {
            console.log('Attempting login...');
            const { user } = await loginService(email, password);
            console.log('Login successful:', user);
            setUser(user);
            navigate('/dashboard');
            return user;
        } catch (error) {
            console.error('Login error:', error);
            throw error;
        }
    };

    const register = async (userData) => {
        try {
            console.log('Attempting registration...');
            const { user } = await registerService(userData);
            console.log('Registration successful:', user);
            setUser(user);
            navigate('/dashboard');
            return user;
        } catch (error) {
            console.error('Registration error:', error);
            throw error;
        }
    };

    const logout = () => {
        console.log('Logging out...');
        logoutService();
        setUser(null);
        navigate('/login');
    };

    const value = {
        user,
        loading,
        login,
        register,
        logout,
        isAuthenticated: !!user
    };

    return (
        <AuthContext.Provider value={value}>
            {!loading && children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

export default AuthContext;
